-- Chrome-assisted pass on the Florida east coast leads (docs/browser-prompts/08), 2026-11-01. Own-page wording only.
-- Villages Recreation "Mah Jongg 101: Beginners": the district's course page says "Learn to play American Mah Jongg, a popular game in the community." and "Each attendee must have a 2026 National MahJongg Card"; non-residents may register. Every section is full (waitlist), so no sessions are listed.
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-01', "description" = 'The Villages district government''s course page says: "Learn to play American Mah Jongg, a popular game in the community." and requires "a 2026 National MahJongg Card". Open to non-residents as well as residents (non-resident registration opens a few days later); the beginner sections fill quickly and use a waitlist.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'the-villages-mah-jongg-101-beginners-villages-recreation' AND "status" = 'NEEDS_REVIEW';
-- Levis JCC (Boca Raton): the ticket page says "Mah Jongg students are required to bring a 2026 National Mah Jongg card".
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-01', "description" = 'The JCC''s ticket page says: "Mah Jongg students are required to bring a 2026 National Mah Jongg card". Beginner lessons with Deborah Aronstam on Monday and Wednesday mornings in two-week sessions ($125), in the MP Rooms at the Levis JCC.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'boca-raton-levis-jcc-phyllis-harvey-sandler-center-beginner-mah-jongg' AND "status" = 'NEEDS_REVIEW';
-- Mahj on the Beach (Kari Long): own site, "American Mahjong lessons, corporate events, fundraisers, international retreats & more!". Its museum sessions are already listed under West Palm Beach (Boca Raton History Museum Mahjong).
UPDATE "Instructor" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-01', "notes" = 'Its own site says: "American Mahjong lessons, corporate events, fundraisers, international retreats & more!" Lessons and open play at the Schmidt Boca Raton History Museum, the Seagate Hotel in Delray Beach and other South Florida venues; book online. The museum sessions are listed under West Palm Beach.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'boca-raton-mahj-on-the-beach-kari-long' AND "status" = 'NEEDS_REVIEW';
-- Temple Beth El Day Circle: members only, advanced players only, no American wording.
UPDATE "Club" SET "status" = 'INACTIVE', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'boca-raton-temple-beth-el-of-boca-raton-mah-jongg-day-circle' AND "status" = 'NEEDS_REVIEW';
